import type { ExpoConfig } from "expo/config";

// Platform file: permissions, background modes and native plugins change through a `platform` issue.
const config: ExpoConfig = {
  name: "Kip",
  slug: "kip",
  scheme: "kip",
  version: "0.1.0",
  orientation: "portrait",
  userInterfaceStyle: "automatic",
  ios: {
    // Placeholder: set to the team's bundle ID once the Apple developer account is ready.
    bundleIdentifier: "com.durhack.kip",
    supportsTablet: false,
    infoPlist: {
      NSMicrophoneUsageDescription:
        "Kip measures how loud your bedroom is overnight. Clips with speech never leave your phone.",
      NSLocationWhenInUseUsageDescription:
        "Kip uses your location to compare your nights with the city's noise sensors nearby.",
      // Keeps metering while the phone is locked on the nightstand
      UIBackgroundModes: ["audio"],
    },
  },
  web: { output: "single", bundler: "metro" },
  plugins: [
    "expo-router",
    "expo-status-bar",
    [
      "@kingstinct/react-native-healthkit",
      {
        NSHealthShareUsageDescription:
          "Kip reads your Apple Watch sleep stages, heart rate, HRV and breathing rate to show which noises woke you.",
        // Kip only reads health data
        NSHealthUpdateUsageDescription: false,
        background: false,
      },
    ],
    "@maplibre/maplibre-react-native",
  ],
  experiments: { typedRoutes: true },
};

export default config;
=== .env.example
# Copy to .env. Secrets never go in the repo or an agent prompt (docs/ARCHITECTURE.md, "Env vars").
# Every variable is optional in development; production needs MONGO_URI and TIGER_URI.
# One line per variable, grouped by feature.

# platform: local databases from `bun run db:up`
PORT=3000
MONGO_URI=mongodb://localhost:27017/kip
TIGER_URI=REDACTED
WEB_DIST=

# labels, briefing: Gemini (paid tier, billing enabled)
GEMINI_API_KEY=
# labels, briefing: ElevenLabs
ELEVENLABS_API_KEY=

# evidence: Solana mainnet, a small funded keypair used only for memos
SOLANA_RPC_URL=
SOLANA_KEYPAIR=

# works: Street Manager open data over SNS
STREET_MANAGER_TOPIC_ARN=

# app: where the iPhone or Expo web dev server finds the API. Use your Mac's LAN IP for a phone.
EXPO_PUBLIC_API_URL=http://localhost:3000

# app: Mapbox public token (pk.) for the web map. Restrict it to the dashboard origins.
# iOS still uses MapLibre. Never commit a real token.
EXPO_PUBLIC_MAPBOX_TOKEN=

# infra (Terraform only, not read by the app): see infra/terraform.tfvars.example
VULTR_API_KEY=
MONGODB_ATLAS_PUBLIC_KEY=
MONGODB_ATLAS_PRIVATE_KEY=
TF_VAR_admin_ip=

