import { useState } from "react";
import { StyleSheet, View } from "react-native";
import { type MapFeatureCollection, MapView } from "@/lib/map";
import { Screen, Text } from "@/lib/ui";

// TEMPORARY local check for #114 overlays on iOS. Not committed: revert after the check.
const SAMPLE: MapFeatureCollection = {
  type: "FeatureCollection",
  features: [
    { type: "Feature", id: "NCL-N01", geometry: { type: "Point", coordinates: [-1.604, 54.9696] } },
    { type: "Feature", id: "NCL-N02", geometry: { type: "Point", coordinates: [-1.6137, 54.9737] } },
    { type: "Feature", id: "NCL-N03", geometry: { type: "Point", coordinates: [-1.6142, 54.9782] } },
    { type: "Feature", id: "NCL-N04", geometry: { type: "Point", coordinates: [-1.615, 54.9786] } },
    { type: "Feature", id: "NCL-N05", geometry: { type: "Point", coordinates: [-1.6131, 54.9777] } },
    {
      type: "Feature",
      id: "works-1",
      geometry: {
        type: "LineString",
        coordinates: [
          [-1.626, 54.9712],
          [-1.619, 54.9704],
          [-1.611, 54.9679],
        ],
      },
    },
    {
      type: "Feature",
      id: "area-1",
      geometry: {
        type: "Polygon",
        coordinates: [
          [
            [-1.6005, 54.975],
            [-1.5925, 54.975],
            [-1.5925, 54.9795],
            [-1.6005, 54.9795],
            [-1.6005, 54.975],
          ],
        ],
      },
    },
  ],
};

export function CityScreen() {
  const [selected, setSelected] = useState<string | null>("NCL-N01");
  return (
    <Screen>
      <Text variant="title">City sleep map</Text>
      <Text>Selected: {selected ?? "none"}</Text>
      <View style={styles.map}>
        <MapView
          features={SAMPLE}
          cluster
          selectedId={selected}
          onSelect={(selection) => {
            console.log("[map-check] selected", selection?.id ?? null);
            setSelected(selection?.id ?? null);
          }}
          onCameraChange={(camera) => console.log("[map-check] camera", JSON.stringify(camera))}
        />
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({ map: { height: 360 } });

