import hashlib, re, subprocess, urllib.request
def h(s): return hashlib.sha256(s.encode()).hexdigest()[:12]
env = dict(l.split("=", 1) for l in open(".env", encoding="utf-8").read().splitlines() if "=" in l and not l.startswith("#"))
want = {"web": h(env.get("EXPO_PUBLIC_MAPBOX_TOKEN", "")), "mobile": h(env.get("EXPO_PUBLIC_MAPBOX_MOBILE_TOKEN", ""))}
def get(url, headers=None):
    req = urllib.request.Request(url, headers=headers or {"User-Agent": "kip-check"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return r.read().decode("utf-8", "replace")
def check(label, base, headers=None):
    try:
        html = get(base + "/", headers)
    except Exception as e:
        print(f"{label}: cannot load ({e})"); return
    srcs = re.findall(r'src="([^"]+\.(?:js|bundle)[^"]*)"', html)
    found, missing_msg = set(), False
    for s in srcs:
        js = get(s if s.startswith("http") else base + s, headers)
        missing_msg |= "Set EXPO_PUBLIC_MAPBOX_TOKEN" in js
        for t in re.findall(r"pk\.[A-Za-z0-9_\-]+\.[A-Za-z0-9_\-]+", js):
            found.add(h(t))
    print(f"{label}: {len(srcs)} script(s); web token baked in: {want['web'] in found}; mobile token baked in: {want['mobile'] in found}; other pk tokens: {len(found - set(want.values()))}")
check("deployed https://kip.edenmatrix.xyz", "https://kip.edenmatrix.xyz")
check("local Metro http://localhost:8081", "http://localhost:8081", {"User-Agent": "kip-check", "expo-platform": "web"})
EOF

